const api = game.modules.get("seattle-by-night")?.api;
if (!api) return ui.notifications.error("The Ward File: the module isn't active in this world.");
const NOCHES = api.Datos?.totalNoches ?? 8;
const actual = Number((await api.estado())?.noche) || 0;
if (actual >= NOCHES) return ui.notifications.warn("Halloway's Clock is already on the last night (" + NOCHES + ").");
await api.noche(actual + 1);
